export interface CatTrack extends Track {
  cats: string[]
}

function build(r: Raw): CatTrack {
  const [id, title, artist, duration, cats] = r
  return {
    id,
    source: 'youtube',
    title,
    artist,
    artistHandle: '',
    artwork: `https://i.ytimg.com/vi/${id}/hqdefault.jpg`,
    artworkLarge: `https://i.ytimg.com/vi/${id}/maxresdefault.jpg`,
    duration,
    playCount: 0,
    streamUrl: '',
    cats: cats ? cats.split('|') : [],
  }
}

export const HOLLYWOOD_TRACKS: CatTrack[] = RAW.map(build)

/** Artists present in the catalog, in harvest order (used for the chips). */
export const HOLLYWOOD_ARTISTS: string[] = ["Taylor Swift","Ed Sheeran","The Weeknd","Ariana Grande","Justin Bieber","Billie Eilish","Dua Lipa","Bruno Mars","Adele","Coldplay","Imagine Dragons","Maroon 5","Katy Perry","Lady Gaga","Rihanna","Beyonce","Eminem","Drake","Post Malone","Kendrick Lamar","Travis Scott","Michael Jackson","Queen","The Beatles","Elton John","Nirvana","Linkin Park","Green Day","Guns N' Roses","Bon Jovi","U2","Red Hot Chili Peppers","Metallica","OneRepublic","Shawn Mendes","Charlie Puth","Sam Smith","Sia","Selena Gomez","Miley Cyrus","Harry Styles","Olivia Rodrigo","Doja Cat","SZA","Calvin Harris","David Guetta","Marshmello","Avicii","Alan Walker","The Chainsmokers","Zedd","Chris Brown","Usher","Nicki Minaj","Lana Del Rey"]

/** Songs by a given artist chip label. */
export function hollywoodByArtist(label: string): CatTrack[] {
  return HOLLYWOOD_TRACKS.filter((t) => t.cats.includes(label))
}
